import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const disposables = [];

  // ===== LOAD GEARS =====
  const gearAData = ctx.glbLoader.load(config.assets.meshUrl);
  const gearA = gearAData.scene;
  gearA.scale.set(1.6, 1.6, 1.6);
  gearA.position.set(0, 0, 0);
  group.add(gearA);

  const gearB = gearA.clone();
  gearB.scale.set(0.9, 0.9, 0.9);
  gearB.position.set(1.15, 0.35, -0.1);
  group.add(gearB);

  // ===== JEWEL PIVOT =====
  const jewelGeom = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color(0xff2a38),
    transmission: 0.6,
    ior: 1.76,
    emissive: new THREE.Color(0xff2a38),
    emissiveIntensity: 1.8,
  });
  const jewel = new THREE.Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);
  group.add(jewel);
  disposables.push(jewelGeom, jewelMat);

  // ===== ARBOR SHAFTS =====
  const shaftGeom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(0x16161d),
    metalness: 0.4,
    roughness: 0.6,
  });

  const shaft1 = new THREE.Mesh(shaftGeom, shaftMat);
  shaft1.position.set(0, 0, 0);
  group.add(shaft1);

  const shaft2 = new THREE.Mesh(shaftGeom, shaftMat);
  shaft2.position.set(1.15, 0.35, -0.1);
  group.add(shaft2);

  disposables.push(shaftGeom, shaftMat);

  // ===== CONTACT SHADOW =====
  const shadowGeom = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.5,
    metalness: 0,
    roughness: 1,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -1.2, 0.01);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);
  disposables.push(shadowGeom, shadowMat);

  // ===== BACKDROP WITH RADIAL GRADIENT =====
  const textureSize = 256;
  const data = new Uint8ClampedArray(textureSize * textureSize * 4);

  for (let y = 0; y < textureSize; y++) {
    for (let x = 0; x < textureSize; x++) {
      const dx = x - textureSize / 2;
      const dy = y - textureSize / 2;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const maxDist = Math.sqrt(textureSize * textureSize / 2);
      const normalizedDist = Math.min(dist / maxDist, 1);

      let r, g, b;
      if (normalizedDist < 0.65) {
        const t = normalizedDist / 0.65;
        const c1 = [0x0b, 0x0b, 0x10];
        const c2 = [0x10, 0x10, 0x17];
        r = Math.round(c1[0] + (c2[0] - c1[0]) * t);
        g = Math.round(c1[1] + (c2[1] - c1[1]) * t);
        b = Math.round(c1[2] + (c2[2] - c1[2]) * t);
      } else {
        const t = (normalizedDist - 0.65) / 0.35;
        const c1 = [0x10, 0x10, 0x17];
        const c2 = [0x16, 0x16, 0x1d];
        r = Math.round(c1[0] + (c2[0] - c1[0]) * t);
        g = Math.round(c1[1] + (c2[1] - c1[1]) * t);
        b = Math.round(c1[2] + (c2[2] - c1[2]) * t);
      }

      const idx = (y * textureSize + x) * 4;
      data[idx] = r;
      data[idx + 1] = g;
      data[idx + 2] = b;
      data[idx + 3] = 255;
    }
  }

  const backdropTex = new THREE.DataTexture(data, textureSize, textureSize, THREE.RGBAFormat);
  backdropTex.magFilter = THREE.LinearFilter;
  backdropTex.minFilter = THREE.LinearFilter;
  backdropTex.needsUpdate = true;

  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshStandardMaterial({
    map: backdropTex,
    metalness: 0,
    roughness: 1,
  });
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdropGeom, backdropMat, backdropTex);

  // ===== TEXT CONTENT =====
  const headlineText = ctx.fontAtlas.createText('The going train', {
    font: 'Lora',
    fontSize: 68,
    fontWeight: 600,
    letterSpacing: -0.005,
    color: 0xe8ecf2,
  });
  headlineText.position.set(0, -1.7, 0);
  group.add(headlineText);

  const captionText = ctx.fontAtlas.createText('34 COMPONENTS / HAND-FINISHED', {
    font: 'JetBrains Mono',
    fontSize: 18,
    fontWeight: 400,
    letterSpacing: 0.08,
    color: 0xe8ecf2,
  });
  captionText.position.set(0, -2.1, 0);
  group.add(captionText);

  // ===== ROTATION ANIMATIONS =====
  const periodPrimary = (2 * Math.PI) / 0.08;
  const periodSecondary = (2 * Math.PI) / 0.142;

  const rotTimeline = gsap.timeline({ repeat: -1 });
  rotTimeline.to(gearA.rotation, { z: Math.PI * 2, duration: periodPrimary, ease: 'none' }, 0);
  rotTimeline.to(gearB.rotation, { z: -Math.PI * 2, duration: periodSecondary, ease: 'none' }, 0);
  timelines.push(rotTimeline);

  // ===== APPLY CINEMATIC PRIMITIVES =====
  if (ctx.primitives?.orbit) {
    ctx.primitives.orbit(group, {
      speed: 0.08,
      radius: 0.2,
    });
  }

  // ===== FOG INFO FOR SCENE =====
  group.userData.fog = new THREE.Fog(0x0b0b10, 5, 11);

  // ===== EVENT HANDLERS =====
  group.userData.handlers = {};

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => {
      if (item && typeof item.dispose === 'function') {
        item.dispose();
      }
    });
  };

  return group;
}
